 "Seçtiğiniz teklif":{de:"Ihr gewähltes Angebot",fr:"Devis choisi",en:"Your chosen quote",ar:"العرض الذي اخترته",fa:"پیشنهاد انتخابی شما",ru:"Выбранное предложение",nl:"Uw gekozen offerte"},
